(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20+Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.18)*20+Math.sin(x*0.013+t*0.22)*15;
  const w2x = Math.sin((x+w1x)*0.025+t*0.3)*10+Math.cos((y+w1y)*0.02-t*0.25)*8;
  const w2y = Math.cos((y+w1y)*0.025-t*0.28)*10+Math.sin((x+w1x)*0.022+t*0.32)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.5],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,-0.3],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.7],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,-0.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.4],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,-0.6],
    [80+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.3+1)*40,0.14,1.3,0.8],
    [400+Math.cos(t*0.45+2)*70,200+Math.sin(t*0.65+4)*50,0.11,1.8,-0.4]
  ];
  let aS=0,iS=0,bS=0;
  for(const[sX,sY,f,sp,ph]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp+ph);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5+ph);
    bS+=Math.sin(d*f*1.5-t*sp*1.3+ph*2)*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,brd=bS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin(sx*0.08+sy*0.06+t*1.5)*0.5+Math.sin(sx*0.15-sy*0.12+t*2.2)*0.25;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2+1)*0.7+Math.sin(dist*0.06-ang*2+t*0.8+2)*0.5)/2.2;
  const cX=sx*0.08,cY=sy*0.08;
  const cell=Math.sin(cX)*Math.sin(cY)+Math.sin((cX+cY)*0.7+t*0.5)*0.5+Math.sin(cX*1.5-cY*0.8+t*0.7)*0.3;
  const raw=act-inh*0.7+bg*0.25+spiral*0.4+brd*0.15;
  const diffused=Math.tanh(raw*1.8);
  const local=Math.tanh((diffused+cell*0.3+Math.sin(diffused*3.14)*0.2)*1.5);
  const dx=Math.abs(Math.sin((sx+1)*0.15)*Math.sin(sy*0.15)-Math.sin((sx-1)*0.15)*Math.sin(sy*0.15));
  const dy=Math.abs(Math.sin(sx*0.15)*Math.sin((sy+1)*0.15)-Math.sin(sx*0.15)*Math.sin((sy-1)*0.15));
  const edge=Math.min(1,(dx+dy)*8);
  const glow=Math.max(0,local)**2*1.5;
  const v=local*0.5+0.5;
  const pal=[[12,15,58],[20,50,100],[18,95,120],[25,150,135],[60,180,120],[180,185,70],[220,165,60],[215,110,65],[180,60,75],[100,30,65],[40,18,55],[12,15,58]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum=0.75+glow*0.4+Math.sin(local*Math.PI)*0.15;
  const eB=1.0+edge*0.3;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/400*0.15;
  return[Math.min(255,(r0*lum*eB+glow*40)*vig)|0,Math.min(255,(g0*lum*eB+glow*30)*vig)|0,Math.min(255,(b0*lum*eB+glow*50)*vig)|0];
}
